using System;using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Forms { public class Patient360Form:Form {TextBox search=new TextBox();ListBox results=new ListBox();Label profile=new Label();
 public Patient360Form(){Text=Localization.Persian?"نمای ۳۶۰ بیمار":"Patient 360";BackColor=Color.FromArgb(225,243,239);Dock=DockStyle.Fill;FormBorderStyle=FormBorderStyle.None;PageChrome.Header(this,Text,Localization.Persian?"پرونده، بیمه، حساسیت‌ها و تاریخچه دارویی":"Profile, insurance, allergies and medication history",Color.FromArgb(18,145,126),Color.FromArgb(52,96,151));Build();}
 void Build(){search.SetBounds(28,160,430,36);search.TextChanged+=(s,e)=>LoadPatients();results.SetBounds(28,215,360,430);results.SelectedIndexChanged+=(s,e)=>ShowProfile();profile.SetBounds(420,215,520,220);profile.BackColor=Color.FromArgb(245,250,249);profile.Padding=new Padding(24);profile.Font=Theme.Font(10);var history=new DataGridView{Left=420,Top=450,Width=520,Height=195,ReadOnly=true,AllowUserToAddRows=false};Theme.StyleGrid(history);results.SelectedIndexChanged+=(s,e)=>{var it=results.SelectedItem as Item;if(it!=null)try{history.DataSource=PatientHistoryRepository.Load(it.Value.Id);}catch{}};Controls.Add(search);Controls.Add(results);Controls.Add(profile);Controls.Add(history);LoadPatients();}
 void LoadPatients(){results.Items.Clear();try{foreach(var p in PatientRepository.Search(search.Text))results.Items.Add(new Item(p));}catch{}}
 void ShowProfile(){var i=results.SelectedItem as Item;if(i==null)return;var p=i.Value;profile.Text=(Localization.Persian?"نام: ":"Name: ")+p.FullName+"\n\n"+(Localization.Persian?"کد ملی: ":"National ID: ")+p.NationalCode+"\n\n"+(Localization.Persian?"بیمه: ":"Insurance: ")+p.Insurance+" "+p.InsuranceNo+"\n\n"+(Localization.Persian?"حساسیت‌ها: ":"Allergies: ")+p.Allergies+"\n\n"+(Localization.Persian?"بیماری‌های زمینه‌ای: ":"Conditions: ")+p.ChronicConditions+"\n\n"+p.Notes;}
 class Item{public PatientProfile Value;public Item(PatientProfile p){Value=p;}public override string ToString(){return Value.FullName+"  •  "+Value.NationalCode;}}
 } }